// Built-in tool contract names, stable across releases (seeded by
// migrationV1). Names are the connections-local selection key from a
// Connection's provider to the adapter contract that dispatches its work.
const (
	toolNameModelResponses = "model-responses"
	toolNameGitHubRead     = "provider-rest-read"
	toolNameGitHubMutate   = "provider-rest-mutate"
	toolNameHTTPPublicRead = "public-http-read"
	toolNameMemoryRead     = "memory-read"
	toolNameMCPProbe       = "mcp-probe"
)

// providerValidationTool maps a connection's provider identity to the
// built-in tool contract connection.validate probes it with. This is a
// connections-local convention (the frozen contract does not name adapters
// by provider string); unmapped providers admit no built-in probe.
var providerValidationTool = map[string]string{
	"openai":           toolNameModelResponses,
	"openai-responses": toolNameModelResponses,
	"responses":        toolNameModelResponses,
	"github":           toolNameGitHubRead,
	"http":             toolNameHTTPPublicRead,
	"httpread":         toolNameHTTPPublicRead,
	"public-http":      toolNameHTTPPublicRead,
	"serenity":         toolNameMemoryRead,
	"memory":           toolNameMemoryRead,
	"serenity-memory":  toolNameMemoryRead,
	"mcp":              toolNameMCPProbe,
}

// buildValidationAction generates the exact adapter action connection.validate
// admits for the connection's selected built-in tool. It returns
// capability_unsupported, never an invented generic probe, when the selected
// adapter accepts only actions this connection cannot honestly supply (for
// example every GitHub and Serenity action needs a specific repository or
// brain that a Connection definition does not carry).
func buildValidationAction(toolName string, conn connectionRow) (json.RawMessage, *contract.Fault) {
	switch toolName {
	case toolNameModelResponses:
		// prepare_session carries no resource beyond the credential itself:
		// it is the one Responses action every model-responses connection
		// can honestly probe with.
		raw, err := json.Marshal(map[string]any{
			"schema": "zatiti.responses.action/v1",
			"kind":   "prepare_session",
		})
		if err != nil {
			return nil, internalError("encoding the prepare_session validation action failed")
		}
		return raw, nil

	case toolNameHTTPPublicRead:
		if len(conn.Destinations) == 0 {
			return nil, capabilityUnsupportedFault(
				"connection %s names no destination to read for public-http-read validation", conn.ID)
		}
		url := conn.Destinations[0]
		if !strings.HasPrefix(url, "http://") && !strings.HasPrefix(url, "https://") {
			url = "https://" + url
		}
		raw, err := json.Marshal(map[string]any{
			"schema":              "zatiti.httpread.action/v1",
			"kind":                "read",
			"url":                 url,
			"method":              "GET",
			"headers":             []any{},
			"expected_media_type": "text/html",
		})
		if err != nil {
			return nil, internalError("encoding the httpread validation action failed")
		}
		return raw, nil

	case toolNameMCPProbe:
		// open_session is the one mcp-probe action every mcp connection can
		// honestly probe with: it carries no resource beyond the client's
		// own self-identification, exactly like model-responses'
		// prepare_session above. list_tools additionally needs an already
		// open session_handle, which connection.validate does not have.
		raw, err := json.Marshal(map[string]any{
			"schema":         "zatiti.mcp.action/v1",
			"kind":           "open_session",
			"client_name":    "zatiti",
			"client_version": "1.0.0",
		})
		if err != nil {
			return nil, internalError("encoding the mcp open_session validation action failed")
		}
		return raw, nil

	case toolNameGitHubRead, toolNameGitHubMutate, toolNameMemoryRead:
		// GitHubReadRepository, the GitHub mutation kinds and both supported
		// Serenity read kinds all require a specific repository or brain
		// identity that a Connection definition does not name. Sending a
		// synthesized repository/brain would be exactly the invented
		// generic probe the assignment forbids: refuse honestly instead.
		return nil, capabilityUnsupportedFault(
			"the %s adapter accepts only resource-specific actions (a named repository or memory brain); "+
				"connection.validate has no generic probe for it", toolName)

	default:
		return nil, capabilityUnsupportedFault("provider %q names no built-in validation adapter", conn.Provider)
	}
}

// capabilityUnsupportedFault builds the capability_unsupported refusal used
// when the selected adapter accepts only actions this connection cannot
// honestly supply.
func capabilityUnsupportedFault(format string, args ...any) *contract.Fault {
	return fault(contract.CodeCapabilityUnsupported, format, args...)
}
